import type { SkillId } from './data';

/**
 * I venti Contatti di Talagaad (Guida del Gamemaster p.22-41): chi sono, dove
 * trovarli, cosa offrono e cosa chiedono. In gioco sono Campioni con il profilo
 * del PNG suggerito per il loro Archetipo.
 */
export interface ContactProfile {
 name: string;
 group: string;
 archetype: string;
 /** il PNG del bestiario da cui prende le Capacità */
 npc: string;
 /** +1d alle Attività dell’Intermezzo con questa Abilità */
 skill: SkillId;
 description: string;
 motivation: string;
 meeting: string;
 favours: string;
 needs: string;
 allies: string;
 gossip: string;
 secret: string;
}

export const CONTACT_PROFILES: ContactProfile[] = [
 {
 name: 'Karoline von Kassel',
 group: 'I Grandi e i Potenti',
 archetype: 'Lord',
 npc: 'nobile-imperiale',
 skill: 'comando',
 description: 'Karoline von Kassel è la Baronessa di Hermsdorf, la città più meridionale del Talabecland lungo la Vecchia Strada della Foresta. La sua famiglia governa l’insediamento da secoli, accontentandosi di controllare un ducato relativamente modesto, raccogliendone i benefici. O così era finché Karoline von Kassel non ascese al comando della famiglia, poiché la sua sete di ricchezze e potere andava ben oltre Hermsdorf, tanto che negli ultimi anni si è trasferita a Talagaad, portando con sé gran parte della propria corte. Pur non avendo alcun potere formale a Talagaad, oltre al privilegio derivato dal suo rango, possiede comunque un’influenza non irrilevante e, infatti, guardie, mercanti, esattori e soldati le prestano attenzione, anche se non tutti credono che otterrà il controllo della città. Le si oppongono infatti numerose gilde cittadine, oltre ai nobili di Talabheim, molti dei quali, a torto o a ragione, la ritengono responsabile della diminuzione della loro influenza sul porto.',
 motivation: 'Ottenere il controllo della Vecchia Strada della Foresta, reclamando tutto il denaro e il prestigio che deriverebbero da un simile potere.',
 meeting: 'Von Kassel tiene corte nella sua lussuosa casa cittadina lontana dalla Piazza del Mercato, oppure dipinge paesaggi mozzafiato nella sua modesta tenuta a sud di Talagaad. Gli alleati Bronzo possono aspettarsi di incontrarla, con discrezione e in un momento scelto dalla nobile, negli alloggi della servitù.',
 favours: 'Gli alleati Oro o Argento possono aspettarsi di mangiare e bere gratuitamente o di essere presentati a individui potenti per un favore; in alcuni casi la Baronessa può prestare denaro, ma è una donna scaltra e si aspetta un pagamento rapido con interessi. Menzionare il suo nome è in genere sufficiente per assicurarsi un alloggio gratuito presso le locande lungo la Vecchia Strada della Foresta.',
 needs: 'Von Kassel usa gli agenti per scortare carovane mercantili lungo la Vecchia Strada della Foresta, affrontare le razzie dei briganti e investigare la corruzione tra i guardastrada. A Talagaad assolda spie per scoprire i segreti dei suoi nemici e altro da sfruttare nelle negoziazioni. Documenti genealogici, veri o falsificati, che le permettessero di avanzare pretese su Talagaad sarebbero bene accetti.',
 allies: 'Van Obelmann è una spina nel fianco della Baronessa e lei sta tramando affinché la sua occupazione di Talagaad fallisca. Tuttavia, riconosce che il Branco da Guerra del Cervo Massacrato abbia causato significativi disagi al commercio e sta facendo pressione al Tenente Klossner e ai Lungosguardo di Talagaad perché si dimostrino più aggressivi nei confronti degli Uominibestia. Von Kassel ha parlato con gli Elfi Silvani della Fratellanza di Serac, e nonostante abbiano alcuni obiettivi comuni, entrambe le parti sono sospettose l’una dell’altra. Ha anche corteggiato i Ludenhof nell’Osterlund, nella speranza che usino le loro risorse per rendere più sicuri i viaggi a nord del confine.',
 gossip: 'Gran parte degli abitanti della città non si fida di estranei e aristocratici, ma von Kassel parla come se volesse aiutare Talagaad e la sua gente a stare a testa alta. I suoi soldi potrebbero favorire le fortune del porto, magari permettendogli anche di diventare un porto libero, responsabile del proprio destino. Molti pensano che queste siano tutte frottole e che voglia semplicemente impossessarsi della città.',
 secret: 'Karoline ha lavorato con alcuni individui sgradevoli per realizzare le sue ambizioni, finanziando briganti per attaccare avversari politici, bande di strada per sabotare l’occupazione di Talabheim e perfino streghe per poter ricattare i leader dei culti. Sebbene sia stata attenta, in caso questi legami dovessero venire alla luce, cadrebbe in disgrazia. baRonessa kaRoline von kassel “Se desideri tenere in mano un serpente, devi afferrarlo in modo deciso. Avvicinati con cautela e ti morderà. La Vecchia Strada della Foresta che si snoda attraverso il Granducato non è poi tanto diversa e io vorrei stringere il serpente per la testa e per la coda, governando non solo Hermsdoft e Talagaad, ma la strada stessa. Ovviamente, chiunque mi aiuterà si guadagnerà una generosa ricompensa…” - Baronessa Karoline von Kassel',
 },
 {
 name: 'Giselbert Almayda',
 group: 'I Grandi e i Potenti',
 archetype: 'Arcanista',
 npc: 'astronomo-di-corte',
 skill: 'volonta',
 description: 'Il potere magico di Giselbert Almayda si è manifestato per la prima volta dopo che i suoi ricchi genitori sono arrivati a Talabheim dall’Estalia. Le sue capacità furono riconosciute da un Mago di nome Eike von Hath, che lo introdusse nell’Hexenguilde. Dopo il suo apprendistato, Almayda ha servito come Mago da Battaglia insieme all’11° Talabheim, guadagnandosi il soprannome di “Bruciaorchi”, durante una campagna minore contro un’incursione di Pelleverde nella parte orientale del Granducato. Mentre la stella di Almayda era in ascesa, von Hath si ritirò a Talagaad per continuare i suoi esperimenti arcani lontano dai Maghi curiosi della capitale. I due continuarono a scriversi fino all’ultimo inverno, quando il suo ex maestro smise di rispondere, lasciandosi alle spalle solo il suo laboratorio, le cui mura portavano segni di fiamme così roventi da sciogliere la pietra. Lasciando il suo posto a Talabheim tra mille speculazioni, il giovane Mago da Battaglia si è trasferito a Talagaad, alla ricerca di qualsiasi indizio su cosa possa essere accaduto al suo maestro. Finora, i Maghi che vivono al porto dicono di non sapere nulla della sorte di von Hath, ma Almayda è sospettoso e sempre più allibito dai loro esperimenti arcani.',
 motivation: 'Scoprire il destino di von Hath e investigare gli abusi magici in città. Verena. Condivide la sua collezione di artefatti di dubbia origine, come la strana pelliccia impacchettata in una cassa e un teschio con tre corna, solo con chi ha la sua fiducia.',
 meeting: 'Almayda può essere trovato nei meandri del suo laboratorio, una tozza casa in pietra ai margini della città, oppure mentre disquisisce con i suoi compagni dell’Hexenguilde nel loro attuale luogo d’incontro.',
 favours: 'Almayda è un potente Mago, ma ha le sue preoccupazioni. Si può discutere con lui di argomenti arcani in cambio di una buona birra, ma presta il suo sapere magico ai personaggi solo se serve per qualcosa legato ai suoi interessi oppure in cambio di informazioni sull’Hexenguilde o sulla sparizione del suo maestro.',
 needs: 'Almayda si affida ad alleati per le sue investigazioni sull’Hexenguilde, in quanto diversi membri sono diventati sospettosi delle sue domande e in molti sono riluttanti a parlare con lui di von Hath. Ha ancora degli obblighi verso l’11° Talabheim che chiede ad altri di portare a termine.',
 allies: 'Almayda è amico di Ambrosia Alacera, anche se considera il suo fascino per i Poteri Perniciosi alquanto sospetto. Sta negoziando un accordo d’affari con Eascylla Sereth e gli Alti Elfi, nella speranza di apprendere di più dai Maghi di Ulthuan. Giselbert nutre particolare disgusto per la Necromanzia e sta facendo pressioni affinché Heinrich Böttcher venga espulso dall’Hexenguilde. Giselbert ha sentito voci di una cacciatrice di streghe che si muove per Talagaad (Grisela Brunhammer) e dormirebbe sonni molto più tranquilli se la donna morisse in circostanze misteriose.',
 gossip: 'La reputazione del Bruciaorchi è ben nota tra i soldati e il numero di Pelleverde che si dice abbia sconfitto aumenta ogni volta che la storia viene raccontata, al punto che è un mistero come possano esisterne ancora. Alcuni sospettano che Almayda prenda parte a terribili esperimenti e complotti, voci messe in giro da Maghi che disprezzano la sua mentalità moralista.',
 secret: 'Almayda non crede che Eike von Hath sia morto, ma è convinto sia intrappolato, risucchiato in un regno di orrore e rovina. Il giovane Mago vuole punire chi ha imprigionato il suo maestro e conoscere i segreti del rituale che von Hath stava tentando di eseguire, per riportarlo indietro.',
 },
 {
 name: 'Ambrosia Alacera',
 group: 'I Grandi e i Potenti',
 archetype: 'Custode delle Tradizioni',
 npc: 'funzionario-imperiale',
 skill: 'memoria',
 description: 'Crescendo nella Contea, Ambrosia Alacera adorava le torte e le frittate quanto ogni altro Halfling, ma era altrettanto attirata da luoghi, persone e oggetti proibiti, come il bosco vicino a casa sua, strani viandanti provenienti dalla Sylvania e il contenuto dei borselli della gente alta. Gli anziani della sua famiglia ricorrevano ad antichi avvertimenti, racconti di bambini Halfling che si erano allontanati troppo, portati via dai Bisulchi, bestie che camminano sulle zampe posteriori. Tuttavia, invece di tenere a freno Ambrosia, queste storie non facevano altro che intrigarla e, crescendo, ascoltava racconti sussurrati ed esagerati attorno a focolari e falò, iniziando perfino a prendere appunti. Ciò era molto diverso da quello che facevano i suoi coetanei e presto se ne andò per conto suo. Si stabilì così a Talagaad, ascoltando le storie dei mercanti itineranti e dei popolani fuggiti da villaggi isolati. La maggior parte sono frutto di superstizioni e pessime birre, ma alcuni dettagli sono stranamente coerenti, come l’affermazione che gli Uominibestia del Talabecland si adornino con i teschi dissacrati dei cervi prediletti da Taal. Alacera ora è molto più vecchia, ma la sua attrazione per gli argomenti proibiti non è diminuita. Parla un Reikspiel fluente, ma, quando conversa con altri abitanti della Contea o si emoziona, ricade in un dialetto Contese molto stretto. Rispetta le divinità Halfling, ma è più vicina al Culto di',
 motivation: 'Alacera non gradisce che le venga detto che qualcosa è proibito. Desidera accumulare informazioni su molti argomenti vietati, dalla falsificazione alle creature innaturali, tuttavia sottovaluta quanto sia pericoloso il suo lavoro, non solo per lei, ma per chiunque le stia a fianco.',
 meeting: 'Alacera potrebbe emergere da dietro una pila di libri nella sua biblioteca per discutere argomenti profani davanti a delle torte ripiene, oppure studiare con sospetto un nuovo arrivo in città.',
 favours: 'Alacera offrirà consigli o materiale da leggere su molti argomenti agli alleati che lo chiedono con gentilezza. Concederà di accedere alla sua collezione di tomi proibiti, che include un grimorio necromantico e una copia quasi completa del famigerato Liber Perditium, solo in cambio di un enorme favore.',
 needs: 'Non viaggia più come un tempo, quindi ha bisogno di altri per investigare piste particolarmente intriganti, come esplorare antiche rovine, boschi oscuri o recuperare artefatti illeciti.',
 allies: 'Di tanto in tanto, Alacera e Giselbert Almayda condividono libri. Non le piace Cox Contafrottole, perché sostiene contribuisca alla cattiva reputazione degli Halfling, e, nonostante la sua abilità come esploratore, è riluttante ad assoldarlo. Jaime de Sabatin le ha venduto diversi reperti interessanti nel corso degli anni, anche se le sue domande sulla loro provenienza sembrano turbarlo.',
 gossip: 'Qualche anno fa è rimasta coinvolta in uno scandalo, dopo che un libro di valore, Un Catalogo delle Tombe dell’Antica Città di Lahmia, è sparito dalla biblioteca personale di un nobile. Vista la nomea degli Halfling per i furti, i sospetti sono subito caduti su di lei e, dato che il libro non è mai stato trovato, le voci non l’hanno ancora abbandonata.',
 secret: 'Una piccola chiazza di pelle secca, quasi squamosa, sta lentamente crescendo sulla sua pancia prominente. Continua a ripetersi che si tratta di una semplice irritazione, ma l’istinto di sopravvivenza l’ha spinta a nascondere la macchia, perfino ai suoi alleati.',
 },
 {
 name: 'Eascylla Sereth',
 group: 'I Grandi e i Potenti',
 archetype: 'Cospiratore',
 npc: 'mercante-elfo',
 skill: 'percezione',
 description: 'Eascylla Sereth è a capo di una piccola ambasciata a Talagaad per i commercianti fluviali degli Alti Elfi. La sua posizione è precaria, lontana dal supporto del suo Reame e malvista dalla comunità di Nani Imperiali di Talagaad, che afferma che la sua presenza nel Vecchio Mondo violi l’antica tregua tra i loro popoli. Sereth affronta la sfida con diplomazia e astuzia, diffondendo la sua influenza per tutto il porto e fino alla corte del Duca Ludwig a Talabheim. Confermando la veridicità di diverse voci sui Nani, Sereth si è dimostrata un’abile e spietata maestra delle spie e raccoglie informazioni per i suoi superiori a Ulthuan, sfruttando il Talabec e il Reik per inviare comunicati segreti alle comunità Elfiche di Marienburg e oltre. Mentre si stabiliva a Talagaad, Sereth è venuta a sapere delle gallerie segrete sotto il Taalbaston e le usa per i movimenti segreti dei suoi agenti dentro e fuori da Talabheim. Sereth sospetta che i suoi superiori a Ulthuan abbiano un interesse per Talagaad e Talabheim che va oltre il tenere d’occhio uno degli aspiranti al trono dell’Impero, ma deve ancora scoprire quale. che deve ereditare vengano cedute a un altro se dovesse rimanere lontano ancora a lungo.',
 motivation: 'Esercitare influenza politica a Talagaad per preservare la sua posizione e inviare informazioni a Ulthuan.',
 meeting: 'Sereth lavora circondata dal lusso Elfico dell’ambasciata di Havenspar, ma potrebbe anche spuntare nelle stanze private di una taverna di lusso o, inaspettatamente, nella camera da letto di un personaggio.',
 favours: 'Sereth non fa quasi nulla gratis, ma è interessata a favorire la crescita di potenziali risorse, fornendo qualche occasionale segreto su importanti figure locali. In cambio di un favore, può fornire accesso ai tunnel dei contrabbandieri sotto al Taalbaston. Non parlerà mai degli affari degli Elfi, considerandolo un gesto pari al tradimento.',
 needs: 'Sereth tratta i suoi agenti come strumenti, indirizzandoli con precisione alle informazioni di cui ha bisogno. Potrebbe mandarli a pedinare un rivale commerciale, a trovare elementi per ricattare qualcuno, a ostacolare i suoi nemici o a consegnare importanti informazioni lungo il fiume.',
 allies: 'Sereth è determinata a esercitare maggiore influenza sull’Hexenguilde e spera di servirsi di Giselbert Almayda per riuscirci. Wyldaroc Passosvelto è un alleato provvisorio che le fornisce informazioni e, a volte, Sereth fa leva sui favori che le spettano per proteggerne l’indipendenza. Capita che i Ghigni Rossi sistemino qualche spiacevole situazione per conto suo e Gruginn Dokrilson è stato una risorsa utile per il contrabbando lungo il fiume, anche se interagisce con lui indirettamente per salvaguardare il suo orgoglio di Nano. Il Clan Gritlok ha sondato le difese della sua operazione, intimidendo i suoi agenti e tentando di seguirli fino a lei.',
 gossip: 'La gente sussurra che Sereth abbia potenti abilità magiche in grado di far capitolare Talagaad, se lo volesse, e lei incoraggia queste voci a ogni occasione.',
 secret: 'Sereth è pentita di un’unica azione intrapresa nel suo periodo a Talagaad. Per mettere pressione al Magistrato Anselm Ragguser affinché supportasse una riforma legale, ha fatto prendere ostaggio suo fratello Jogann, ma, in seguito a una sfortunata spirale di eventi, Jogann è finito ucciso per mano dei suoi agenti. Nonostante Sereth sia convinta di aver distrutto tutte le prove che potrebbero incriminarla, sa che Ragusser sta ancora cercando l’assassino del fratello.',
 },
 {
 name: 'Horst von Schmettoch',
 group: 'I Grandi e i Potenti',
 archetype: 'Nobile in Disgrazia',
 npc: 'nobile-imperiale',
 skill: 'fascino',
 description: 'Si può incontrare il presunto Lord Horst von Schmettoch mentre beve o scommette la sua ingente ma sempre meno cospicua eredità in una delle taverne di Talagaad. Suo padre, Lord Johannes von Schmettoch, gestiva con grande cura le sue tenute ancestrali a est, arricchendo ulteriormente le sue fortune quando prese in moglie Satara, la figlia maggiore di una potente casa mercantile dell’Arabia, e si trasferì con la famiglia a Talabheim. Horst, il loro unico figlio, sembra determinato a infangare il buon nome di famiglia, con grande disappunto dei suoi genitori. Per anni, a corte Horst era l’anima della festa, ma le sue avventure giovanili sono finite in tragedia quando ha ucciso Martin Feuerbach in duello a causa dei sentimenti che provavano per la stessa donna. I duelli sono normali tra la nobiltà di Talabheim, ma non sono quasi mai alla morte, quindi l’unico erede degli Schmettoch venne esiliato con ignominia a Talagaad. Molti lo vedono come un imbarazzo o un bersaglio facile, ma è un ottimo compagno di bevute e, con sorpresa tanto di Horst quanto di chiunque altro, un amico leale.',
 motivation: 'Tornare a Talabheim. Nonostante affermi di amare la dissolutezza sfrenata di Talagaad, desidera ancora il dramma e la politica di corte e teme che le terre',
 meeting: 'Horst potrebbe apparire una qualsiasi notte in una qualsiasi taverna, prima di barcollare verso le sue stanze un tempo raffinate, in una residenza di famiglia lungo la Via del Mago.',
 favours: 'Davanti a un bicchiere di vino, Horst spettegolerà liberamente di qualsiasi famiglia nobile della regione, ma spesso le sue informazioni sono vecchie di qualche anno. Le sue fortune sono scemate, ma in cambio di un favore presterà una carrozza, abiti da corte o altri averi nobiliari ai suoi amici. È più attento con il suo denaro, poiché la sua disponibilità si sta velocemente prosciugando e ogni taverna di Talagaad piangerà il giorno in cui sarà esaurita.',
 needs: 'Horst desidera trovare un modo per tornare alla corte di Talabheim ed è sempre alla ricerca di qualche modo per guadagnarsi il rispetto della nobiltà della capitale o di sabotare quello dei Feuerbach. I suoi piani sono spesso mal concepiti e sempre rischiosi, perciò eventuali volontari che gli diano una mano sono sempre ben accetti.',
 allies: 'Horst detesta la Baronessa von Kassel, che crede abbia spinto Martin Feuerbach ad accettare il duello. Spesso beve insieme a Rosamunde Nemevich, una dei pochi che non tentano di sfruttarlo in qualche modo. Horst e Tordi Trondottir vanno sorprendentemente d’accordo, accomunati dal desiderio di migliorare la propria condizione. Horst vorrebbe unirsi ai Cavalieri Ottiliani, anche se nel suo stato attuale nemmeno loro lo accetterebbero, e ha avuto frequenti discussioni con Klossner e i Lungosguardo di Talagaad. Nonostante le sue molte malefatte, il suo sangue nobile l’ha protetto da conseguenze più serie.',
 gossip: 'Alcuni affermano che Martin Feuerbach sia sopravvissuto al duello e si stia semplicemente nascondendo come parte di un qualche complotto politico contro i von Schmettoch. Altri invece dicono che Horst abbia mancato il bersaglio e qualcun altro abbia sparato il colpo mortale, ma che lui fosse troppo ubriaco per accorgersene.',
 secret: 'Nonostante lo neghi, lo stesso Johann von Schmettoch si è divertito parecchio in gioventù e Horst ha un fratello maggiore illegittimo di nome Reuben, che suo padre ha minacciato di nominare erede, in caso Horst non si redima in fretta. hoRst',
 },
 {
 name: 'Leonard Van Obelmann',
 group: 'Compagni d’Arme',
 archetype: 'Generale',
 npc: 'nobile-imperiale',
 skill: 'comando',
 description: 'Quando Leonard van Obelmann si fece un nome nell’Incidente della Drakwald, durante l’ultimo scontro aperto con il Reikland, circa trent’anni fa, era soltanto un capitano delle forze di Talabheim, ma nel giro di pochi anni è asceso al grado di Lord Cacciatore, un generale delle Truppe Provinciali del Talabec. Anche se la sua stella è ormai in declino, al termine della sua lunga carriera, van Obelmann ha vissuto un ultimo momento di gloria quando è riuscito a convincere il Duca Ludwig a concedergli un reggimento per occupare Talagaad, con l’intenzione di fortificare il porto contro quello che ritiene un inevitabile attacco delle forze di Sigismund Ulric dell’Osterlund. A Talagaad, van Obelmann è spesso il vituperato e spietato volto dell’eccesso di Talabheim, ma quelli che conoscono personalmente il Lord Cacciatore hanno visto un lato più tenero. È il patrono di molti soldati e paga di tasca propria per assicurarsi che chi è rimasto ferito in servizio sotto il suo comando sia curato dal Culto di Shallya. Il teschio che porta sul cappello appartiene a Ernst, suo fratello, un giovane ufficiale morto decenni fa e molti pensano che sia un bel modo per onorarlo.',
 motivation: 'Fortificare Talagaad, spazzare via i criminali e gli scansafatiche che potrebbero indebolire la città in caso di assedio e gestire il porto con l’efficienza di un accampamento militare.',
 meeting: 'Van Obelmann ha eretto il suo quartier generale in un ex tempio di Myrmidia lontano dalla Via del Mago, ora convertito nella caserma fortificata dell’11° Talabheim. Quando non impartisce ordini a ufficiali dalle divise eleganti, si riposa nelle sue stanze a Sponda Fredda, circondato da trofei delle vittorie passate.',
 favours: 'Van Obelmann è incorruttibile e non fa concessioni. Fornisce armi o addestramento a chiunque lo richieda, in quanto dà valore all’essere preparati. Fornisce supporto dall’11° Talabheim solo in caso ciò aiuti la difesa della città.',
 needs: 'Van Obelmann vuole pacificare Talagaad, come decine di persone prima di lui hanno tentato di fare senza successo, oltre a fortificarla contro ogni attacco. Ha bisogno di agenti che sopprimano il dissenso al porto, consegnino importanti piani militari ed esplorino il territorio oltre le mura. Sa bene che la maggior parte della gente di Talagaad non vuole la sua presenza, quindi si affida ad altri per lavorare tra le strade in suo nome.',
 allies: 'Van Obelmann comanda l’11° Talabheim, conosciuto come le “Carogne” dalla popolazione scontente di Talagaad e, in teoria, anche i Lungosguardo di Talagaad, anche se li considera soldati di seconda categoria. Tra gli ufficiali dei Lungosguardo, il Tenente Klossner sembra il più promettente, anche se van Obelmann non si fida completamente del giovane. Il Lord Cacciatore sa che la Baronessa von Kassel sta tentando di sabotare il suo operato e apprezzerebbe rispedirla a Hermsdorf. Ha subito ustioni terribili combattendo contro il Cacciatore di Streghe Haslav nella Drakwald e da allora nutre un odio incrollabile per i Sigmariti.',
 gossip: 'Le storie delle sue imprese di guerra contro il Principato del Reikland sono entrate nella leggenda ed è opinione diffusa che si sia schierato per un’ulteriore intensificazione del conflitto che si spingesse fino ad Altdorf, potendo. In pochi sanno che fu uno degli artefici del trattato che sancì il termine delle ostilità.',
 secret: 'A volte, lo si può sentire bisbigliare al teschio del fratello. Di rado, quando è da solo, Ernst risponde. loRd cacciatoRe leonaRd',
 },
 {
 name: 'Danya Klossner',
 group: 'Compagni d’Arme',
 archetype: 'Ufficiale',
 npc: 'soldato-provinciale-imperiale',
 skill: 'difesa',
 description: 'Danya Klossner è nato e cresciuto a Talagaad da genitori di origini Kislevite e non ha mai pensato di lasciare questo sudicio porto, se non quando è incaricato di farlo. Unitosi ai Lungosguardo di Talagaad come semplice recluta, Klossner ha raggiunto il rango di tenente attraverso perseveranza, competenza e diligente risoluzione dei problemi lasciati dagli altri ufficiali del reggimento. In forte contrasto con le Carogne da poco giunte a Talagaad, Klossner, come molti dei Lungosguardo, si accontenta di chiudere un occhio sulla criminalità locale, ancora più della Guardia Cittadina. Dopotutto, molti dei ladri e contrabbandieri a cui dovrebbe dare noia sono parenti o amici di famiglia e Klossner ritiene che il principale dovere dei Lungosguardo sia difendere Talagaad dalle minacce esterne, un compito che il giovane ufficiale prende molto seriamente. Anche se i Lungosguardo si sono spesso dimostrati carenti, Klossner crede che rimarrebbero saldi a difesa della città e non è chiaro se le Truppe Provinciali di Talabheim farebbero lo stesso, considerato che sarebbe molto più semplice ritirarsi verso le difese di gran lunga superiori del Taalbaston. Quindi, un giorno i Lungosguardo potrebbero essere l’ultima linea di difesa di Talagaad, pensiero che allo stesso tempo emoziona e terrorizza il Tenente. Un tempo, Talabheim era uno dei centri della fede Ulricana e Skovgaard spera che torni a esserlo. Molti la considerano una fanatica, ma in quanto famosa disertrice dall’Osterlund, gode di un certo sostegno ufficiale. È una presenza belligerante per le strade di Talagaad, istigando campagne sempre più aggressive per liberare la Grande Foresta dai Goblin e dagli Uominibestia nel nome di Ulric.',
 motivation: 'Tenere Talagaad al sicuro da Uominibestia, Goblin, gente dell’Osterlund e altri forestieri che potrebbero minacciarla, inclusi quelli provenienti da Talabheim.',
 meeting: 'La postazione di Klossner è una solitaria guardiola lungo la Via del Mago e gestisce anche un ufficio ben tenuto in mezzo alla confusione della caserma dei Lungosguardo.',
 favours: 'Corruzione e tangenti accompagnano i Lungosguardo da generazioni e Klossner è felice di acquistare armi o armature basilari per un amico o intercedere in caso qualcuno che conosce abbia delle incomprensioni con le Carogne. Fornire accesso alle aree riservate, torri di guardia e simili, è più rischioso, soprattutto con i soldati di Talabheim in giro, ma fattibile, se deve un favore a qualcuno.',
 needs: 'Klossner è sempre alla ricerca di modi per rafforzare le difese della città e il reggimento non ha mai abbastanza munizioni. Il Tenente apprezza anche chiunque sia disposto a esplorare oltre le mura cittadine in cerca di minacce o chi può fornire informazioni compromettenti sui soldati delle Carogne, con cui Klossner ha spesso divergenze.',
 allies: 'Le Carogne dell’11° Talabheim ridicolizzano apertamente il reggimento di Klossner, definendolo squallido e incompetente, poco più di una milizia. Il loro comandante, il Lord Cacciatore van Obelmann non è altrettanto pomposo e sembra mostrare un interesse personale per Klossner, sufficiente a rendere chiunque nervoso. Il Tenente pensa che l’ossessione di van Obelmann per l’Osterlund sia insensata, quando la Tribù Okki Rotzi è un pericolo molto più presente. Klossner e i Ghigni Rossi hanno da anni un accordo e il Tenente guarda dall’altra parte quando le loro attività non fanno male a nessuno, ma se la banda alzasse il tiro, dovrebbe rispondere delle proprie azioni.',
 gossip: 'Il Capitano dei Lungosguardo di Talagaad, Olaf Kundert, non è più un ragazzino e presto si ritirerà. Il giovane Tenente Klossner è uno dei suoi potenziali successori.',
 secret: 'Uno dei soldati di Klossner, Sorge Krumptmann, si è indebitato con il boss della malavita Klaus Duvelt qualche anno fa. Quest’ultimo ha accettato di azzerare il suo debito in cambio di otto favori da parte di Klossner e finora ne hanno conclusi cinque, ognuno peggiore del precedente. tenente',
 },
 {
 name: 'Manfreda Skovgaard',
 group: 'Compagni d’Arme',
 archetype: 'Veterano',
 npc: 'prete-guerriero-di-ulric',
 skill: 'mischia',
 description: 'Manfreda Skovgaard proviene dal Middenland, anche se non lo chiama più casa. Da giovane, vagò scioccamente per le Colline Ululanti durante una tormenta, andando quasi incontro alla sua fine finché non vide un Lupo Bianco muoversi tra il turbinio della neve. Lo seguì in una caverna alla ricerca di riparo, ma l’animale non era una semplice guida: si scagliò su di lei e lottarono, ma alla fine Skovgaard trionfò piantandogli una roccia congelata nel cranio. Dormendo al caldo della carcassa, comprese che la creatura era un segno di Ulric, una dimostrazione che il dio ricompensa chi ha la forza di tracciare da sé il proprio percorso. Pelliccia in mano, Skovgaard divenne infine una Sacerdotessa Guerriera nelle armate dell’Osterlund, conosciuta per la sua ferocia e fermezza. Tuttavia, la sua carriera giunse al termine quando un nobile di nome Jorunn Eisenhal derise la pelliccia che indossava, ormai rovinata dai segni di molte lame. Le fu consigliato di perdonarlo, poiché gli Eisenhal erano generosi benefattori del culto di Ulric, ma per lei era impensabile e, come aveva fatto tempo addietro nella caverna del lupo, lo picchiò a morte con una roccia raccolta da terra. Skovgaard fu così costretta all’esilio, disgustata da ciò che era diventato il culto.',
 motivation: 'Ricostruire la vera fede di Ulric nel Granducato del Talabecland, trasformando Talagaad in un bastione di fede militante.',
 meeting: 'Predicando ai fedeli in un santuario Ulricano o aiutando ad addestrare la milizia locale.',
 favours: 'Skovgaard è molto istruita nella dottrina Ulricana e offre conoscenza e guida a chiunque. Presterà la sua forza in combattimento a una degna causa, ma solo se ritenga ne possa derivare un beneficio per il suo dio, oltre ad aspettarsi un favore in cambio. Non metterà mai piede nell’Osterlund per alcun motivo.',
 needs: 'Skovgaard è alla ricerca di campioni le cui gloriose vittorie possano ispirare gli altri a seguirne l’esempio.',
 allies: 'Amelinda Hertwier e Skovgaard spesso litigano sulla vera natura delle terre selvagge e su chi sia superiore tra Taal e Ulric, ma si considerano alleate. È meno certa riguardo a Valda Kracht, che sembra devota alla difesa dell’Impero, ma il cui vero credo resta un mistero. La Sacerdotessa Guerriera accompagna regolarmente in pattuglia i Lungosguardo e le Carogne, nella speranza di fare una buona impressione su van Obelmann, ed è determinata a dare la caccia e ad apprendere la verità sulla mostruosità lupina che si dice vaghi per le strade di Talagaad (Frederick Bauer).',
 gossip: 'Alcuni dicono che l’uomo che Skovgaard ha attaccato per aver insultato la sua pelliccia fosse un amico del Conte Sigismund Ulric o un parente alla lontana della famiglia Ludenhof. Se è così, Manfreda si è davvero fatta dei nemici potenti.',
 secret: 'Le sue vecchie ferite di guerra iniziano ad avere la meglio. Non lo ammetterebbe mai, ma a breve non sarà più in grado di accompagnare i fedeli di Ulric in battaglia e ispirare i fedeli a Talagaad potrebbe essere l’ultima occasione di servire il suo dio.',
 },
 {
 name: 'Cox Contafrottole',
 group: 'Compagni d’Arme',
 archetype: 'Esploratore',
 npc: 'ladro-halfling',
 skill: 'tiro',
 description: 'Cox rafforza, e sfrutta, lo stereotipo secondo cui gli Halfling sono solo dei piccoli ladruncoli. È un tipo allegro che racconta così tante storie che nessuno è sicuro del suo passato, anche se, di tanto in tanto, afferma che non può tornare nella Contea. La verità è che Cox è diventato orfano in giovane età e si è unito ad una banda di ladri Halfling, finché non è stato abbandonato nel mezzo di un’audace rapina e lasciato ad affrontare le conseguenze. Cox è sfuggito ai suoi inseguitori e si è dato alla macchia. Dopo essere finito a Talagaad, si è unito ai Lungosguardo, dove lavora come esploratore. Cox trova l’elastico approccio dei Lungosguardo alla legge e all’ordine piacevolmente accomodante per le sue attività secondarie. Oltre ad aiutare a piazzare merce rubata e a commerciare nel mercato nero di Talabheim, conosce diverse gallerie sotto al Taalbaston che aiutano i contrabbandieri a entrare e a uscire dalla città. Quando non si sta riempiendo le tasche, adempie con riluttanza ai suoi obblighi nei confronti dell’Esercito Provinciale, pattugliando la Grande Foresta e avvertendo tempestivamente di eventuali pericoli incombenti. Pur talvolta esagerando sui dettagli dei suoi successi, Cox è un segugio e un arciere davvero abile.',
 motivation: 'Vivere la vita al massimo ed evitare le conseguenze delle sue azioni criminali.',
 meeting: 'Sono ben poche le locande a Talagaad da cui Cox non sia bandito. Lo si potrebbe incontrare nella sala comune del Letto del Fiume o vicino una bancarella che vende cibo di cui si lamenta ad alta voce, anche mentre lo divora avidamente.',
 favours: 'A parte condividere racconti, Cox non fa quasi nulla gratis. Tuttavia, gli piace vantarsi di saper portare chiunque ovunque, ma solo in cambio di un favore. Infatti, Cox è coinvolto in una fittissima rete di favori da restituire, truffe in corso, imbrogli e inganni di ogni tipo ed è sempre alla ricerca di nuovi collaboratori o di altri bersagli.',
 needs: 'Cox deve giostrare i suoi impegni militari e criminali, quindi paga spesso degli amici per occuparsi di uno mentre lui gestisce l’altro. Ai personaggi al corrente delle sue attività potrebbe chiedere di mappare il territorio degli Uominibestia, cacciare un mostro pericoloso o derubare un barcone commerciale.',
 allies: 'Lotti Babkina ha accolto Cox quando nessun altro voleva farlo, perciò è l’unica persona che lui non tradirebbe o contrarierebbe mai. È riuscito a farsi buone le Carogne, fornendo loro informazioni utili e conducendo le sue attività criminali con discrezione. A Cox manca il cameratismo dei suoi compagni Halfling e spera di legare con Ambrosia Alacera, pur sapendo che lei non lo rispetta. Si è scontrato con razziatori Nogor dal Branco da Guerra del Cervo Massacrato, ma nutre un particolare rancore per gli “orribili piccoli Goblin” della Tribù Okki Rotzi.',
 gossip: 'Nessun pettegolezzo su di Cox potrebbe eguagliare le storie che lui racconta su se stesso, ma alcuni dicono che sotto quella scorza allegra si nasconda una spia calcolatrice al soldo della Contea.',
 secret: 'Cox è riuscito a tenersi un oggetto dalla grande rapina alla Contea: il sigillo dell’Anziano della Contea. Nei documenti ufficiali è stato ormai sostituito da tempo, ma potrebbe facilmente ingannare chi non ne è al corrente.',
 },
 {
 name: 'Rosamunde Nemevich',
 group: 'Compagni d’Arme',
 archetype: 'Vecchio Soldato',
 npc: 'miliziano-della-libera-compagnia',
 skill: 'muscoli',
 description: 'Rosamunde Nemevich è nata a Slavyanaska, una città Kislevita lungo il Talabec Superiore, ma se ne andò non appena fu grande abbastanza da unirsi a una Libera Compagnia Imperiale, dove sopportò anni di fatica in mezzo al fango, guardando i suoi amici morire e ricevendo ordini da persone molto più stupide di lei. Quando un comandante particolarmente incompetente inviò la sua unità in un’imboscata degli Okki Rotzi, Nemevich riuscì a trascinarsi lontano e abbandonò il campo di battaglia. Trovò un guaritore del Talabecland che curò le sue ferite, anche se le disse che avrebbe avuto bisogno delle stampelle per il resto della vita. Nemevich non tornò al suo reggimento, nella speranza che la credessero morta e, prima di finire a Talagaad, vagò per un po’ tra i villaggi del Talabecland. Nemevich è una combattente esperta e determinata, ma fatica a trovare lavoro regolare e spesso accetta incarichi discutibili solo per mettere qualcosa sotto ai denti. Nonostante la sua situazione disperata, qualcosa in lei si è rifiutato di lasciarla morire sul campo di battaglia e non la abbandonerà di certo ora. nobiltà, dovere che svolge con riluttanza, perché, sebbene riconosca che si tratta di un ruolo importante, è convinto che un giorno gli costerà la vita.',
 motivation: 'Sopravvivere in qualsiasi modo. Cercare di lasciarsi il passato alle spalle.',
 meeting: 'Nemevich può essere incontrata nelle locande o taverne più economiche, oppure mentre fa la guardia, con poca convinzione, fuori da un incontro tra criminali o da una bisca clandestina.',
 favours: 'Nemevich conosce molti veterani in congedo, molti dei quali condividono segreti sul loro periodo in servizio, come tesori sotterrati, rovine infestate e altre cose che li tengono svegli la notte. Può mettere in contatto un personaggio con altri veterani in cambio di una bevuta e un pasto modesto; tuttavia, è riluttante a parlare delle sue esperienze e per farlo chiede in cambio un favore importante.',
 needs: 'Nemevich accetta qualunque lavoro riesca a trovare, quindi in genere pericoloso, criminale o politicamente delicato. Nonostante sia troppo orgogliosa per accettare la carità dei suoi amici, potrebbe affermare di fare loro un favore coinvolgendoli nei suoi stessi lavori, così che possano tenerla d’occhio.',
 allies: 'Nemevich non si fida di van Obelmann, che le ricorda i bastardi che hanno mandati i suoi amici a morire. Klossner ha tentato di reclutarla come istruttrice nei Lungosguardo di Talagaad, ma senza successo. Ogni tanto esce a bere con Horst, Gruginn Dokrilsone il resto della feccia della società di Talagaad e talvolta accetta lavori dai Ghigni Rossi. Nemevich nutre un odio profondo per la Tribù Okki Rotzi e nulla la spinge a entrare in azione, come sentire parlare delle loro attività in zona.',
 gossip: 'Si dice che abbia ucciso il suo comandante per aver condotto la sua unità in un’imboscata. Vero o meno, il suo sguardo truce fa sì che tutti ci credano.',
 secret: 'Un Cavaliere Ottiliano che un tempo ricevette supporto dall’unità di Nemevich è passato in città di recente. L’ha vista e ha incrociato il suo sguardo per diversi momenti. Teme che l’abbia riconosciuta e che riveli che è una disertrice.',
 },
 {
 name: 'Yury Kagan',
 group: 'Il Popolino',
 archetype: 'Anziano',
 npc: 'cittadino-imperiale',
 skill: 'lancio',
 description: 'Yury, che non usa mai il suo cognome, è figlio di un Boiaro Kislevita, ma in quanto settimogenito aveva ben poca eredità ad attenderlo. In gioventù scese lungo il Talabec, lasciandosi le fredde steppe alle spalle, alla ricerca di un futuro e ora ha vissuto molto più tempo nell’Impero di quanto sia stato nel Kislev, ma parla ancora della sua casa con un affetto intriso di nostalgia. Nella sua vita ha fatto dozzine di lavori, dal manovale, al soldato e perfino il maniscalco, e, pur non essendo mai diventato ricco, ha abbastanza soldi per affrontare la vecchiaia, una rarità a Talagaad come in ogni altro luogo. Sia i Kisleviti che gli abitanti del Talabecland rispettano gli anziani per tradizione e Yury ha più consigli da offrire di molti altri. Condivide racconti di viaggi in chiatta fino ad Altdorf e di inseguimenti di Goblin per le Colline Brulle, oltre a lanciare ancora le asce con una precisione sorprendente. È visto come un leader ufficioso della gente comune di Talagaad e spesso viene chiamato per dare voce alle loro preoccupazioni davanti al magistrato o alla La divisione dell’Impero deriva dal dimenticare Taal e dal credere che il mondo naturale sia un’entità ostile da tenere fuori dietro alte mura. Taal invece è l’unico modo che ha l’Impero per guarire e le persone hanno soltanto bisogno della sua parola. Per questo, è disposta a rinunciare alla pace della foresta.',
 motivation: 'Insegnare alla gente di Talagaad a essere forte. Abbastanza forte per quello che sta arrivando.',
 meeting: 'Yury tiene corte al Riposo del Boiaro. Può essere spesso incontrato mentre osserva con soddisfazione la vita che va avanti, fumando una pipa maleodorante all’angolo di una strada.',
 favours: 'Yury ha un debole per chi ha bisogno di aiuto e, se necessario, può fornire un luogo tranquillo dove riposare o nascondersi. Può fungere da collegamento neutrale tra diverse fazioni, dalle bande criminali alle gilde di mercanti, ma si aspetta un favore in cambio, che spesso usa a beneficio di altri che si sono rivolti a lui per qualche necessità.',
 needs: 'Il suo cuore tenero è attratto dalle cause perse. Quando qualcuno ha bisogno, cerca gente abile per dare una mano e, a volte, è proprio lui che ha bisogno, perché ormai, dopotutto, ha una certa età.',
 allies: 'Yury ha visto crescere molti giovani abitanti di Talagaad, come Danya e Valda, e diventare ciò che sono oggi. Il suo rapporto con Gruginn Dokrilson risale a molto prima, anche se nell’ultimo periodo sembrano evitarsi. Comprende ben poco del potere di Malko Matasca ma, all’insaputa del mistico, in passato ha fatto in modo che alcuni Cacciatori di Streghe non si interessassero a lui. Yury è cresciuto sentendo storie delle Guerre dei Vampiri e ha avuto esperienze dirette con i nonmorti che sono ormai diventate folclore.',
 gossip: 'Yury è temuto da alcuni e rispettato da altri. Tutti sembrano avere una storia in cui lui viene inaspettatamente in loro aiuto o mostra di possedere qualche bizzarra abilità. Nessuno sa di preciso quanto sia vecchio e sicuramente presto passerà a miglior vita, no?',
 secret: 'Nella lunga vita di Yury, l’unico venuto da lui per chiedere aiuto e rifiutato fu suo fratello maggiore, Petar. Il ricordo non ha mai smesso di perseguitarlo.',
 },
 {
 name: 'Amelinda Hertwier',
 group: 'Il Popolino',
 archetype: 'Predicatore',
 npc: 'prete-di-taal',
 skill: 'sopravvivenza',
 description: 'La foresta unisce l’Impero e nel cuore della foresta Taal attende. Questo è il messaggio di Amelinda Hertwier. Arrivata da poco, giunse a Talagaad per ripristinare i santuari di Taal nella Grande Foresta, molti dei quali erano negletti a causa dei crescenti pericoli nel bosco. Quando è in città, Hertwier siede accanto al Viadotto del Mago, predicando la parola di Taal ai passanti. Tuttavia, non le piace ciò che vede, poiché la gente di Talagaad onora Taal, ma le loro vite sono legate alla pietra, al fango e al commercio. Dimenticano che l’Impero è un piccolo luogo all’interno del dominio di Taal e voltano le spalle a tutto ciò che è selvaggio, lasciando che la corruzione si diffonda sotto le fronde della foresta. Non le piace stare a Talagaad e preferirebbe di gran lunga passare le sue giornate nella Grande Foresta, con la sola compagnia delle bestie e degli uccelli, ma il suo compito è verso Taal e, nonostante sia il dio dei luoghi incontaminati, è anche il dio dell’Umanità. Ora è combattuta tra speranza e frustrazione. Nonostante i Barbalunga dei Gritlok si siano offerti, non farebbe mai leva sui suoi contatti per mettere in mostra il suo lavoro, poiché significherebbe che non ha fiducia nelle sue abilità. Quindi, sempre più rancorosa e sospettosa ogni anno che passa, rimane a Talagaad isolandosi nella sua forgia, senza mai abbandonare il sogno che, prima o poi, il suo talento venga riconosciuto.',
 motivation: 'Assicurarsi che i rituali di Taal siano osservati e ripristinare il ruolo di Taal come divinità principale dell’Impero.',
 meeting: 'È possibile incontrare Amelinda mentre predica in un santuario di Taal, oppure da sola nei boschi a contemplarne il dominio.',
 favours: 'Hertwier apprezza parlare delle vie di Taal con chiunque e non richiede alcun pagamento. È anche una cacciatrice esperta e aiuterà chiunque si debba avventurare nelle profondità del bosco, in cambio di un favore. Può richiamare altri servitori di Taal, non tutti Umani.',
 needs: 'Amelinda ha bisogno di aiuto con alcuni rituali nella Grande Foresta. A volte incarica altri di scortare i pellegrinaggi dei fedeli o di andare a caccia al posto suo, in modo da organizzare in città banchetti in onore di Taal.',
 allies: 'Hertwier e Manfreda Skovgaard sono compagne sacerdotesse dei Vecchi Dei e, nonostante si scontrino sui particolari, condividono la visione di un Impero unito dalla fede. Riconosce anche che Malko Matasca è stato toccato da un potere più grande, sebbene il druido tormentato non riconosca le sue abilità per i doni che sono. Hertwier ha rifiutato l’offerta di Hadrogar Siefert di unirsi ai Mastini di Taal e sospetta che i loro bizzarri rituali siano una perversione della vera devozione; tuttavia, ha già collaborato con i Mastini e la Fratellanza di Serac per affrontare il vero nemico, cioè il Branco da Guerra del Cervo Massacrato.',
 gossip: 'L’opinione locale su di lei è divisa. Il suo fervore attrae alcuni e respinge altri, ma rispetta le radici del Talabecland e costituisce un baluardo contro i Sigmariti.',
 secret: 'Gli animali le hanno sempre parlato, cosa che considera una benedizione di Taal. Tuttavia, ultimamente le voci della foresta le stanno riempiendo la mente di furia e sete di sangue, chiedendole con insistenza di distruggere le creazioni dell’uomo, e sta iniziando a temere che alcuni di questi sussurri non giungano davvero dal suo dio.',
 },
 {
 name: 'Tordi Trondottir',
 group: 'Il Popolino',
 archetype: 'Fabbro',
 npc: 'artigiano',
 skill: 'lavoro',
 description: 'Tordi Trondottir è il fabbro più abile di Talagaad o, almeno, secondo lei. Ha una forgia nella Piazza del Mercato, dove il suo martello dirige il ritmo del frastuono del commercio. Anche i fabbri delle montagne riconoscono le sue spade come oggetti eccellenti, nonostante non provengano dall’antica fucina di una fortezza. Tuttavia, Tordi deve ancora creare un capolavoro immortale, qualcosa degno del vero orgoglio Nanico, e sta iniziando a temere che non ci riuscirà mai. Non è una forgiarune e non si illude di poterlo diventare, ma tra i fabbri si dice che un’arma forgiata con abbastanza abilità non abbia bisogno della magia per diventare leggendaria. Ha soltanto bisogno di essere un oggetto ben fatto e impugnato da una mano consona. Tordi è cresciuta tra racconti di armi magnifiche. Mentre gli altri giovani del Clan Gritlok immaginavano di essere Kurgan Barbadiferro o il leggendario Grombrindal, lei sognava di forgiare i loro armamenti. È orgogliosa di prestare la stessa attenzione alla zappa di un contadino che dedicherebbe a un’ascia, ma le armi sono la sua vera passione. Quando si sentì pronta, inviò dei campioni alla nobiltà di Talabheim, sicura che le commissioni sarebbero giunte a fiumi e invece non ottenne alcuna risposta. Pochi si fermano a Talagaad quanto una volta e i soldi iniziano a scarseggiare. Forse alla fine Rhya ha voltato il suo sguardo altrove.',
 motivation: 'Trovare un ricco mecenate e trasferirsi a Talabheim, dove avrà accesso a materiali migliori e all’esperienza di altri fabbri in grado di aiutarla a migliorare le sue abilità.',
 meeting: 'Tordi lavora alla forgia nella Piazza del Mercato e spesso si trova a martellare qualche nuova creazione o a negoziare sul prezzo dei lingotti a una bancarella.',
 favours: 'Tordi valuterà qualsiasi arma, attrezzo o armatura per capirne il valore o la storia. Produrrà oggetti solo in cambio di un favore, poiché crede negli scambi onesti, anche tra amici. È molto rispettata tra i Nani di Talagaad e farà da intermediario per un alleato che ha bisogno di essere presentato o di chiarire un malinteso.',
 needs: 'Tordi invia i suoi amici alla ricerca di materiali rari che possano far risaltare i suoi lavori. Non suggerirebbe mai di rubare, ma non farebbe nemmeno troppe domande sulla provenienza di un oggetto di cui ha molto bisogno.',
 allies: 'Tordi appartiene al Clan Gritlok e ha l’obbligo di servire il suo Thane, Feldrakk Spezzapollici. Come il suo signore, nutre un profondo rancore nei confronti di Gorpak Teztaztramba, il Capo Orco che ha rubato alcune delle sue armi ai precedenti proprietari. Ha minacciato di gettare Jaime de Sabatin nel fiume, dato che ogni volta che le fa visita, spariscono degli oggetti. Tordi non ha concesso i suoi servigi ai Lungosguardo di Talagaadper molti anni, rifiutandosi di contribuire alla corruzione tramite l’emissione di ricevute di acquisto falsificate, ma ha accettato una commissione dall’11° Talabheim.',
 gossip: 'Tordi è rispettata, ma in molti pensano sia difficile avere a che fare con lei. Chi riesce a vedere oltre la sua scortesia sostiene che sia difficile trovare un’amica più leale.',
 secret: 'Alla morte di sua madre, Tordi ha ereditato una lampada runica e la sta studiando in segreto, nella speranza di sbloccarne il vero potere.',
 },
 {
 name: 'Lotti Babkina',
 group: 'Il Popolino',
 archetype: 'Proprietario',
 npc: 'cittadino-imperiale',
 skill: 'percezione',
 description: 'Per qualunque viaggiatore con modeste risorse, la locanda Letto del Fiume è il posto giusto dove alloggiare a Talagaad. Sotto l’attenta gestione della proprietaria Lotti Babkina, il locale è diventato un vivace luogo d’incontro dove la gente del posto si mescola con i viaggiatori per spettegolare. Il nonno di Lotti giunse dal Gran Catai e si trovava a Talagaad quando incontrò sua nonna, un’abitante di Sponda Fredda; insieme aprirono una locanda sulla riva del Talabec, ma con scarso successo. La famiglia sopravvisse e Lotti soffriva la fame, ma quando assunse il controllo dell’attività la loro fortuna cambiò. Attribuisce questo successo al favore di Rhya, tanto che in un angolo della locanda è stato creato un piccolo altare alla dea, e Lotti sa che il Letto del Fiume avrà successo fintanto che la dea le sorriderà. La locanda è ora uno stabilimento ben rispettato, dove trovare un attimo di tregua dai pericoli della strada, e, sebbene Lotti e il suo personale lavorino duro per far sì che resti tale, sembra stiano affrontando una battaglia senza speranza. Le tasse sono aumentate, le spedizioni di cibo interrotte, i banditi tendono imboscate ai viaggiatori di passaggio e la tensione tra gente comune e nobiltà è in aumento. La povertà di Talagaad le assicura un costante flusso di pazienti che non fanno domande, poiché in pochi possono permettersi dottori più affermati. Sono grati della compassione di Genezzo e, nonostante alcuni spiacevoli effetti collaterali, ha senza dubbio salvato più vite di quante ne abbia rovinate.',
 motivation: 'Preservare il Letto del Fiume e passarlo ai figli, onorando Rhya e assicurandosi il favore della dea.',
 meeting: 'Si può trovare Lotti al Letto del Fiume, a meno che non stia letteralmente arrivando la fine del mondo.',
 favours: 'Amici sfortunati possono sempre avere un letto caldo e un pasto semplice alla locanda. Lotti sente tutto ciò che accade nell’Impero da mercanti, mercenari ed esploratori che si fermano da lei. Dà molto valore alla privacy dei suoi clienti e riferirà tali segreti solo se deve un favore a qualcuno.',
 needs: 'Lotti è legata alla sua locanda e si affida agli amici per recuperare merci, proteggere le carovane che le consegnano o negoziare con i fornitori. A volte, chiede aiuto per assicurarsi che i precetti di Rhya vengano osservati, come aiutare le famiglie bisognose.',
 allies: 'Lotti e Cox hanno una lunga storia alle spalle e l’Halfling la aiuta in ogni modo, anche mentre si fa strada attraverso la sua dispensa. Wyldaroc Passosvelto è un intrattenitore regolare al Letto del Fiume e, nonostante Lotti lo trovi irritante, ha sempre qualcosa di interessante da riferire. Alcuni clienti regolari pagano generosamente per una stanza privata dove mangiare quando sono in città e lei non sa che sono cultisti della Fiamma Protetta. Non sa nemmeno che le ripetute offerte di acquisto per la locanda provengono dagli agenti della Cerchia d’Avorio, che sono intenzionati a ottenere il locale a tutti i costi per estendere la loro influenza sui mercanti locali e non accetteranno un rifiuto come risposta.',
 gossip: 'Non è semplice trovare qualcuno che non abbia una parola gentile su Lotti. Alcuni mercanti si fidano più di lei che dei banchieri di Talabheim e si dice che nella sua cantina ci sia una cassaforte con le loro ricchezze.',
 secret: 'I soldi scarseggiano, ma Lotti è riluttante a separarsi dalle ultime reliquie di suo nonno, alcune sete pregiate con una coppia di draghi intrecciati, portati dalla sua casa natale nel Gran Catai. La tradizione di famiglia racconta che quelle sete siano incantate e troppo preziose per essere vendute, ma il tetto della locanda non si riparerà da solo…',
 },
 {
 name: 'Olena Genezzo',
 group: 'Il Popolino',
 archetype: 'Guaritore',
 npc: 'artigiano',
 skill: 'destrezza',
 description: 'Per chi non ha nessun altro a cui rivolgersi, Olena Genezzo offre una varietà di medicazioni economiche e quasi sempre efficaci per ogni malanno. Addestratasi in origine in Tilea, ottenne una licenza dalla Gilda degli Apotecari di Talabheim, dal momento che Talagaad è troppo piccola per averne una propria. Nonostante le sue notevoli abilità chirurgiche, Genezzo ha una pessima reputazione e i bizzarri impiastri ed elisir in vendita nel suo negozio sono tutt’altro che usuali. Tuttavia, si guadagna da vivere offrendo i suoi servizi ai poveri, ai bisognosi e ai criminali, cioè, in sostanza, a chiunque di cui difficilmente si sentirà la mancanza. Il suo vero talento va oltre la semplice conoscenza delle erbe. Per lei, il mondo è vivo. Fin dall’infanzia, riusciva a vedere gli spiriti fluire nell’aria, nei fiumi, negli alberi, donando colore e potere a ogni cosa. Potere che può mischiare nelle sue misture, ottenendo, di solito, trattamenti e rimedi stranamente efficaci. A volte, però, gli effetti si rivelano molto meno desiderabili, a partire da violente convulsioni fino all’insorgenza di escrescenze squamose in tutto il corpo. Genezzo è sempre desiderosa di acquistare ingredienti rari e di sperimentare con la loro applicazione. Tuttavia, vuole soprattutto essere lasciata a gestire la sua attività in pace. Sfortunatamente, tenere un basso profilo è qualcosa che proprio non gli riesce e, quando sorgono problemi, si affida ai suoi amici per tenerlo lontano dalla forca.',
 motivation: 'Perfezionare la sua arte evitando le attenzioni di coloro che vorrebbero sfruttarla o perseguitarla.',
 meeting: 'Genezzo vende unguenti nel suo sudicio negozio nella Piazza del Mercato, ma si reca spesso dai suoi pazienti, magari per sistemare l’osso di un contadino ferito e la mucca che l’ha colpito.',
 favours: 'Un amico può sempre affidarsi a Genezzo perché medichi le sue Ferite, ma, se è necessario un intervento, lei si aspetta un favore. Conosce bene le piante e può analizzare e identificare la maggior parte delle erbe e degli impiastri.',
 needs: 'Genezzo ha sempre bisogno di ingredienti rari per le sue medicine e non ha quasi mai tempo per raccoglierli di persona. È disposta a mostrare i suoi esperimenti falliti solo ai suoi amici più fidati, chiedendo loro di liberarsene.',
 allies: 'Genezzo e Malko Matasca riconoscono il dono l’uno dell’altra e condividono informazioni su potenziali Cacciatori di Streghe, temendo che la scoperta di uno dei due potrebbe portare all’altro. Le Carogne di Talabheim disprezzano le sue pratiche, ma i Lungosguardo di Talagaad si fanno meno problemi e Klossner, Cox o qualsiasi altro loro commilitone è probabilmente finito sotto le cure di Genezzo. Ha stretto un accordo con i Ghigni Rossi: lei sistema le loro ferite e loro la aiutano a liberarsi dei cadaveri; tuttavia, nessuno dei due ha realizzato che le paludi in cui vengono gettati i morti sono state scoperte dalla Megera Troll Kroki, che sta iniziando ad apprezzare il sapore di questi corpi contorti e sta risalendo la corruzione fino alla fonte.',
 gossip: 'Nessuno sa da quale parte della Tilea sia giunta Genezzo, ma voci ricorrenti dicono che sia stata obbligata a fuggire dopo la diffusione di un’ondata di mutazioni tra i malati e morenti della città.',
 secret: 'Nemmeno lei conosce il suo vero potenziale come Elementalista ed è ben felice di tenere limitato quel potere, per paura di cosa potrebbe accadere se lo usasse più apertamente.',
 },
 {
 name: 'Jaime de Sabatin',
 group: 'Fannulloni e Vagabondi',
 archetype: 'Girovago',
 npc: 'brigante',
 skill: 'atletica',
 description: 'Jaime de Sabatin sostiene di essere stato ovunque, dalle sabbie brucianti di Khemri, alla tundra congelata del Kislev. In pochi gli credono, ma è un buon cantastorie e sa intrattenere gli ascoltatori che si fanno impressionare dai suoi racconti di terre lontane. Per la sorpresa di alcuni, de Sabatin è veramente l’avventuriero che afferma di essere. La sua carriera ebbe inizio quando, servendo come Armigero durante una crociata errante destinata a fallire, si imbatté in una tomba Khemriana perduta da tempo, da cui fuggì con le tasche tintinnanti, senza mai più voltarsi indietro. Come ladro di tombe, ha maneggiato e venduto molte rare antichità, ma il suo fiuto per l’avventura è migliore della sua abilità di mercanteggiare, poiché le monete scorrono tra le sue dita come sabbia. Dopo una spedizione in una fortezza Nanica abbandonata finita male, il vagabondo Bretonniano sta tenendo un basso profilo. Riuscì a salvarsi la vita, ma lasciò i suoi compagni a morire e non ci volle molto prima che i Nani del Clan Brandal, che avevano finanziato la spedizione, realizzassero ciò che aveva fatto. Ora un rancore pende sulla sua testa, obbligandolo a nascondersi a Talagaad, il porto in un certo senso più famigerato dell’Impero. La gente del porto si è abituata all’Elfo Silvano e molti si rivolgono a lui per avere notizie da villaggi remoti, dato che spesso viaggia tra di essi raccogliendo musica, pettegolezzi e informazioni lungo il cammino. Di solito resta in città per qualche settimana, ascoltando i racconti e scrivendo nuove canzoni, prima di sparire di nuovo nei boschi, per poi tornare sempre con nuove storie da raccontare.',
 motivation: 'Trovare una nuova e lucrativa avventura. De Sabatin scappa spesso dalle conseguenze delle sue azioni e fa il possibile per avere sempre un passo di vantaggio su quelli che ha derubato o tradito.',
 meeting: 'De Sabatin si vanta della sua vita e delle sue imprese, ognuna più oltraggiosa dell’altra, e le racconta in qualunque taverna disposta ancora a fargli credito.',
 favours: 'De Sabatin parla molto, ma oltre a condividere racconti delle sue imprese, fa ben poco, a meno che non abbia qualcosa da guadagnare. Non può allontanarsi dalla sicurezza di Talagaad e passa le soffiate che riceve da altri, anche se si aspetta una parte dei profitti. Come favore, potrebbe prestare degli oggetti speciali dalla sua collezione personale.',
 needs: 'Quando Jaime viene a sapere di un sito funerario o di una rovina con manufatti da salvare dalle devastazioni del tempo, assolderà un nuovo gruppo di compagni per proteggerlo durante l’avventura, sfruttando poi degli intermediari per vendere il ricavato.',
 allies: 'De Sabatin e Wyldaroc Passosvelto amano condividere storie e il secondo continua a promettergli di scrivere una canzone sulle sue avventure. Ambrosia Alacera è una dei clienti più affidabili di de Sabatin. Il Clan Gritlok ha dei legami con il Clan Brandal e, nonostante non voglia intromettersi nel loro rancore, tiene d’occhio il Bretonniano e non permetterà che questi sfugga alla sua giusta punizione. Un misterioso mecenate guida De Sabatin con allettanti promesse di altre reliquie Khemriane, ma, in verità, si tratta di Zekrakar, che sta sfruttando de Sabatin per infastidire il suo antico nemico, il Sacerdote Liche Khutesh.',
 gossip: 'De Sabatin è famoso per tradire i suoi datori di lavoro e compagni di avventure. Il Bretonniano rifiuta con veemenza questa nomea, perché un paio di incomprensioni non possono essere considerate un’abitudine! Tuttavia, la sua reputazione è ormai consolidata ed è un serio ostacolo quando cerca lavoro.',
 secret: 'Nonostante la sua spavalderia, De Sabatin ha il terrore dei ratti. Una tomba piena di roditori squittenti metterebbe duramente alla prova la sua dedizione all’avventura. Jaime de sabatin',
 },
 {
 name: 'Wyldaroc Passosvelto',
 group: 'Fannulloni e Vagabondi',
 archetype: 'Cantastorie',
 npc: 'miliziano-elfo',
 skill: 'fascino',
 description: 'Gli Elfi Silvani sono visti con sospetto a Talagaad, come ovunque nell’Impero, ma quando Wyldaroc Passosvelto inizia a suonare il suo tamburo, la folla si raccoglie per ascoltarlo in totale silenzio. Molte delle sue ballate sono di composizione Imperiale, racconti dell’Impero al suo apice, delle gloriose vittorie nelle Guerre dei Vampiri o contro Orchi e Goblin secoli o millenni fa. Altre sono canzoni della sua casa nella foresta, che incantano anche coloro che non comprendono le sue parole. Wyldaroc lasciò il Laurelorn per soddisfare la sua ossessione per la musica e le canzoni degli Umani. Per gli standard Elfici si tratta di un’arte ancora grezza, semplice dove dovrebbe essere raffinata, ma che possiede una certa passione aliena alla sua stirpe. Iniziò a raccogliere canzoni per tutto l’Impero, a volte benvenuto, altre volte nascosto poco oltre la luce di un fuoco da campo ad ascoltare con attenzione le canzoni solitarie di viaggiatori nervosi. Ha passato quasi un decennio a Talagaad e dintorni, affascinato dall’influenza Taalita sulla musica, in un certo modo simile alla cultura di casa sua, eppure molto differente sotto altri aspetti. Ultimamente, è turbato da altre visioni di morte e distruzione su una scala che fatica a comprendere. È spaventato dal parlarne con chiunque, per paura di imboccare un sentiero più oscuro che porta alla corruzione… o sulla pira di un Cacciatore di Streghe.',
 motivation: 'Apprendere di più sulla cultura e sulle tradizioni Imperiali, soprattutto musicali, mantenendo così la pace tra l’Impero e i Regni dei Boschi.',
 meeting: 'Wyldaroc suona per le folle in città o nelle piazze dei villaggi, passa per i boschi silenzioso come uno spirito e offre spettacoli privati ai grandi e potenti nelle lussuose abitazioni di Talagaad.',
 favours: 'Wyldaroc condividerà qualunque novità che apprende, anche solo per vedere le reazioni altrui. È uno spirito libero e viaggia verso un luogo specifico, come guida o per raccogliervi informazioni, soltanto se deve ricambiare un favore. Apprezza una bugia ben congegnata quasi quanto la verità, fatto di cui pochi si rendono conto, e, come favore, diffonde volentieri false voci.',
 needs: 'Wyldaroc è sempre alla ricerca di racconti che lo ispirino a scrivere una canzone. Sfortunatamente, non sa tenere i segreti, che spesso finiscono nelle sue creazioni. Deve lealtà alla Fratellanza di Serac e può capitare che abbia bisogno di aiuto per adempiere ai suoi doveri nei loro confronti.',
 allies: 'La relazione di Wyldaroc con la Fratellanza di Serac è complicata. A volte collaborano e, in altre, hanno scopi opposti. Dentro Talagaad, Wyldaroc si esibisce spesso alla locanda di Lotti, dove trova spesso il tempo per bere con Jaime de Sabatin e farsi raccontare la sua ultima idiozia. Molto di rado, visita Talabheim per esibirsi alla corte del Duca Ludwig.',
 gossip: 'Speculare sul suo passato è una delle attività preferite dagli ammiratori. Molti affermano che scappi da qualcosa, con storie che vanno dallo scandalo all’omicidio.',
 secret: 'Quando Wyldaroc lasciò il Laurelorn, portò un onorevole Malevolo con sé, nascosto nel suo tamburo. È stata un’idea dello spirito e, nonostante la creatura sia spesso dormiente, a volte emerge per creare problemi a Wyldaroc e a chi gli sta intorno.',
 },
 {
 name: 'Malko Matasca',
 group: 'Fannulloni e Vagabondi',
 archetype: 'Mistico',
 npc: 'necromante',
 skill: 'volonta',
 description: 'La Grande Foresta è attraversata da molti sentieri, piste della selvaggina che si intrecciano con i percorsi dei taglialegna in una vorticosa rete di arterie ostruita da spine. Solo chi conosce la strada può sperare di trovare la capanna di Malko Matasca nascosta sotto le fronde degli alberi, non lontano dalle mura di Talagaad. Matasca vive da solo, eppure chi gli fa visita giura di sentire altre voci mentre si avvicina alla sua dimora. La famiglia di Matasca ha lasciato l’Estalia quando lui era appena un bambino, fuggendo dalla Guardia Nera di Morr. Quando raggiunse Talagaad era ormai solo, eccetto per i morti, poiché gli spiriti dei defunti gli parlano, mostrandogli visioni, avvertimenti e richieste di aiuto. All’inizio provò ad assisterli tutti, ma gli spiriti sono implacabili e per ognuno che soccorreva, un altro compariva con le proprie richieste. Ora ignora tutte le voci, eccetto le più insistenti. Questi presagi portano Matasca in luoghi dove la morte ha preso o prenderà presto il sopravvento, esortandolo con lievi sussurri e visioni che a malapena comprende. A volte riesce a intuirne il significato, evitare un disastro, far riposare uno spirito o semplicemente ad arrivare nel luogo giusto per assistere a momenti importanti o terribili. È stato condotto a Talagaad proprio dalla visione di un immenso fuoco e di un cervo che ci salta sopra verso la morte, solo per poi rinascere come lupo. Non ha idea di cosa possa significare, ma è sicuramente di grande importanza.',
 motivation: 'Soddisfare i sussurri dei morti e riuscire finalmente a dormire una notte di sonno profondo.',
 meeting: 'Matasca abita nel fitto della foresta, ma potrebbe apparire inaspettatamente davanti alla porta di un personaggio, non invitato né benvenuto.',
 favours: 'Matasca offre spesso indicazioni indesiderate in cambio di nulla, ma sempre avvolte in allegorie e simbolismi. Ha una qualche comprensione della magia, appresa dallo spirito di un necromante morto, ma se ne serve di rado, dato che attira sempre spiriti sgradevoli. Per usarla, si aspetta in cambio un favore.',
 needs: 'Ogni volta che Matasca lascia la sua capanna, è preoccupato che i Cacciatori di Streghe lo trovino. Chiede spesso aiuto ai suoi amici per portare a termine le ultime richieste dei morti, investigare pericoli che ha previsto o consegnare qualcosa che lo aiuti a controllare i suoi poteri.',
 allies: 'Matasca ha incontrato gli spiriti di coloro che Olena Genezzo non è riuscita ad aiutare. I due si comprendono a vicenda e si scambiano informazioni sugli avvistamenti dei Cacciatori di Streghe. Amelinda Hertwier è una sua alleata e Yury lo ha aiutato da giovane, appena arrivato, anche se non ha mai capito perché. Esplorando i limiti della sua magia, Matasca attira l’attenzione degli altri incantatori, che apprezzerebbero la possibilità di sfruttare il suo potere. Questi burattinai includono la Cerchia d’Avorio, il Sacerdote Liche Khutesh e l’Hexenguilde.',
 gossip: 'Matasca ha la reputazione dell’innocuo eremita, un devoto a Taal che si crede abbia scelto l’isolamento nelle terre selvagge. In quanto indovino, ha la reputazione di fare previsioni interessanti, anche se il futuro che annuncia si fa sempre più cupo.',
 secret: 'Una voce cresce sempre più forte, promettendogli il controllo dei suoi doni. Gli ha insegnato occulti segreti oscuri e rituali di sangue che Matasca si rifiuta di eseguire. Per ora.',
 },
 {
 name: 'Gruginn Dokrilson',
 group: 'Fannulloni e Vagabondi',
 archetype: 'Contrabbandiere',
 npc: 'brigante',
 skill: 'furtivita',
 description: 'Pochi Nani si sentono a casa sull’acqua, ma Gruginn non è come gli altri. Guadagna qualcosina trasportando persone lungo il fiume, ma la maggior parte dei suoi soldi provengono da mercato nero e contrabbando. Ciononostante, afferma d’essere un contrabbandiere onesto e un Nano onorevole. Chi tratta con lui sostiene che offra accordi equi, ma non dimentica mai una svista. Gli altri Nani lo evitano perché, onorevole o meno, resta un criminale per le leggi dell’Impero, cosa che soltanto i più testardi non accettano. Molti ritengono uno scandalo che non abbia pronunciato il Giuramento dello Sventratore per riottenere onore per sé e la sua stirpe. Gruginn dice che non gli importa cosa pensano gli altri Nani ma, a volte, l’apparente indifferenza cade e lo si trova ad affogare i dispiaceri in qualche bettola. Non dice mai cosa l’ha spinto alla vita criminale ed è difficile coglierlo in fallo, persino durante gli interrogatori più approfonditi non ha mai ammesso nulla e nessuna accusa ufficiale si è mai rivelata fondata. Sostiene di conoscere una via segreta per entrare nel Taalbaston, così da non disturbare il duro lavoro degli agenti doganali, ignota a tutti gli altri contrabbandieri. Molti colleghi hanno tentato di corromperlo o minacciarlo, ma Gruginn si limita a ridere, sostenendo che si trova sotto al naso di chi ha occhi per vedere, prima di battersi un dito sulla benda.',
 motivation: 'Guadagnarsi da vivere, evitare il lungo braccio della legge e apprendere tutto il possibile sui percorsi dei contrabbandieri sotto al Taalbaston.',
 meeting: 'Il suo sporco barcone, Il Rancore, è spesso ancorato al porto. Quando ha l’opportunità, percorre di persona le gallerie sotto il Taalbaston.',
 favours: 'Gruginn non lavora gratis, ma ha occhio per i cimeli Nanici e li identifica per gli amici. Contrabbanda merci e, se necessario, persone dentro o fuori Talabheim o Talagaad e, in cambio, preferisce informazioni o fatti piuttosto che denaro.',
 needs: 'Gruginn sfrutta un piccolo ma leale equipaggio per creare distrazioni, spostare merci o fornire alibi. La guardia cittadina tiene d’occhio i suoi compari, ma lui può far sì che il gioco valga la candela.',
 allies: 'Gruginn è disposto a lavorare quasi con chiunque. Ha rapporti d’affari di lunga data con i Ghigni Rossi, ma tratta anche con i loro rivali. Ogni tanto, accetta lavori dai Feuerbach e dall’Alta Elfa Eascylla Sereth, che comunica via intermediari e resterebbe sorpresa dallo scoprire che Gruginn sa che è la vera mandante. Il rapporto con le Carogne di Talabheim è ancora in divenire, sono meno corruttibili dei Lungosguardo di Talagaad, ma migliori nell’occuparsi di Goblin e Troll di Fiume. Ogni tanto, contrabbanda testi religiosi per Valda e la Fiamma Protetta, forse per onorare l’amicizia del loro dio con il popolo Nanico.',
 gossip: 'I Nani Imperiali di Talagaad consigliano di stare alla larga da Gruginn. Lo chiamano apostata, un reietto dalle Karak che avrebbe dovuto pronunciare il Giuramento dello Sventratore anni fa. I criminali di Talagaad lo considerano un tipo per bene.',
 secret: 'Gruginn è uno dei molti agenti del Kharl Thorgim Ullekson, inviato a Talagaad per investigare su un rancore, presumibilmente risolto, tra i Nani e la stirpe degli Imperatori Ottiliani. Il Kharl non è convinto che sia sistemato, ma i dettagli sono andati perduti e alcune note riportano che riguardava un grande lavoro d’ingegneria Nanica da qualche parte sotto il Taalbaston.',
 },
 {
 name: 'Valda Kracht',
 group: 'Fannulloni e Vagabondi',
 archetype: 'Eretico',
 npc: 'cultista-sigmarita',
 skill: 'tempra',
 description: 'Valda Kracht udì per la prima volta la parola di Sigmar mentre lavorava come scrivana di un agente esattoriale ai moli di Talagaad. Assalita da un mercante Marienburghese infuriato dalle imposte accumulate, Kracht si salvò quando il successivo mercante in coda gettò l’aggressore della giovane scrivana nel Talabec e la aiutò a rialzarsi. Il nome dell’uomo era Ludwig e fu lui a darle per la prima volta una copia di Ye Comete Heraldes Hine, un libro proibito sulla vita e la saggezza di Sigmar. Da allora la sua fede non ha fatto altro che diventare più profonda. Kracht sfrutta la sua posizione per aiutare i fedeli suoi compagni a entrare o fuggire da Talagaad, dove soltanto uno sciocco predicherebbe il nome di Sigmar apertamente, e la sua nuova vita nell’ombra l’ha resa paranoica. È certa che qualcuno la dichiarerà eretica e verrà portata via nella notte, ma per sostenere la causa di Sigmar ne vale la pena. La sua speranza è che un giorno i suoi concittadini vedano la verità. Sigmar è un dio di sicurezza, unità e protezione. Non deve essere temuto, perché lui è colui che scaccia la paura! Per ora, diffonde il messaggio del suo dio in segreto, contrabbandando predicatori e testi sacri per i moli di Sponda Fredda. Tuttavia, i fuochi della fede bruciano ardenti nel suo cuore ed è solo questione di tempo prima che non riesca più a nasconderli, qualunque siano le conseguenze.',
 motivation: 'Condividere la sua causa con chiunque, proteggendo i fedeli, e risvegliare l’Impero mostrando il male che si diffonde ovunque la luce di Sigmar è stata estinta.',
 meeting: 'Quando Kracht non lavora ai moli, annotando le merci che vengono scaricate, prega in un santuario di Sigmar nascosto nella parte peggiore della città.',
 favours: 'Come scrivana, Kracht sa leggere e scrivere ed è felice di farlo in modo accurato per un amico o alleato. Può alterare i documenti ufficiali, ma è un’attività difficile e pericolosa, quindi lo farà soltanto in cambio di un favore. Cerca di aiutare subito chi condivide la sua fede segreta e forse una folla di Sigmariti potrebbe essere radunata anche a Talagaad, in caso di grande bisogno e per una giusta causa.',
 needs: 'Kracht è sicura di essere sempre osservata e spesso si rivolge agli alleati per metterla in contatto con altri Sigmariti, aiutare altri devoti a fuggire dalla persecuzione o investigare voci su streghe malvagie.',
 allies: 'Kracht e la Fiamma Protetta non sono sempre allineati. È convinta che il loro aperto fanatismo sia più dannoso che utile, oltre che spesso cooptato dall’agenda politica del Reikland; questi, a loro volta, credono che la sua fede sia flebile e fragile, pronta a crollare se messa sotto pressione, mettendo in pericolo i loro obiettivi. Tuttavia, Kracht ha fatto molto per Madre Hase e può contare sul suo supporto quando è necessario. Kracht ha lavorato con Gruginn Dokrilson per trasportare alcuni Sigmariti fuori da Talagaad e spera che Manfreda Skovgaard la accetti quando arriverà il momento di rivelare la sua fede. Da buona Sigmarita, Kracht disprezza gli Orchi, i Goblin e gli incantesimi di streghe e stregoni.',
 gossip: 'Il suo lavoro come scrivana di un agente esattoriale è un motivo sufficiente per evitarla e la sua intensa e ansiosa energia è ancora più scoraggiante. Viene spesso sospettata di nascondere qualcosa, come magari una dipendenza dalla Radice Stramba, o l’aver accettato modeste e accettabili tangenti. In pochi conoscono la sua vera fede.',
 secret: 'Sul letto di morte, sua madre confessò che il figlio, l’unico fratello di Valda, portava il marchio della mutazione ed era stato bandito nella foresta. A volte, Kracht lo sogna, una bestiale e sbuffante creatura che conduce una vita depravata nelle foreste oscure. Teme che in qualche modo anche il proprio sangue sia contaminato e, se un giorno dovessero incontrarsi, si domanda se avrebbe la forza di ucciderlo.',
 },
];

export const contactProfile = (name: string) => CONTACT_PROFILES.find((c) => c.name === name || name.startsWith(c.name));
